    float angle = (float) MathUtils.getAngle(basePoint.x, basePoint.y, handlerBase.x, handlerBase.y);
    UEdge next = controlled.getEdges().iterator().next();
    final float degrees = (float) Math.toDegrees(((double) this.mConstAngleDiff) - (MathUtils.getAngle(next.mStart.x, next.mStart.y, next.mEnd.x, next.mEnd.y) - ((double) angle)));
    controlled.getScene().selectedRange().apply(controlled.getName(), new IUnitOp() { // from class: ru.jecklandin.stickman.units.handlers.manipulators.RotateManipulator$$ExternalSyntheticLambda0
        @Override // ru.jecklandin.stickman.units.IUnitOp
